files.jobs/send-digest.sh:
#!/bin/sh
# send-digest: emails the daily report digest
mailctl send --digest daily

files.jobs/backup-db.sh:
#!/bin/sh
# backup-db: copies the database to backup storage
pg_dump appdb > /backups/appdb.sql

files.jobs/log-indexer-stop.sh:
#!/bin/sh
# log-indexer-stop: stops the log-indexer service
servicectl stop log-indexer
